export function environmentText(key, data = {}) {
  const translated = globalThis.game?.i18n?.format?.(key, data);
  const text = translated && translated !== key ? translated : defaults[key] ?? key;
  return typeof text === "string" ? text.replace(/\{(\w+)\}/g, (match, name) => data[name] ?? match) : text;
}
